<?php if(!defined('ABSPATH'))exit;global $wpdb;$e=ICD_Visitas_Database::table('escolas');$m=ICD_Visitas_Database::table('mediadores');$v=ICD_Visitas_Database::table('vinculos');$schools=$wpdb->get_results("SELECT id,nome FROM $e WHERE ativo=1 ORDER BY nome");$meds=$wpdb->get_results("SELECT id,nome FROM $m WHERE ativo=1 ORDER BY nome");$rows=$wpdb->get_results("SELECT v.*,e.nome escola,m.nome mediador FROM $v v JOIN $e e ON e.id=v.escola_id JOIN $m m ON m.id=v.mediador_id WHERE v.ativo=1 ORDER BY e.nome,m.nome");?>
<div class="wrap icd-admin"><h1>Vínculos Escola × Mediador</h1><form class="icd-form-row" method="post" action="<?php echo esc_url(ICD_Visitas_Helpers::action_url());?>"><?php wp_nonce_field('icd_save_vinculo');?><input type="hidden" name="action" value="icd_save_vinculo"><label>Escola<select required name="escola_id"><option value="">Selecione</option><?php foreach($schools as $x)echo '<option value="'.$x->id.'">'.esc_html($x->nome).'</option>';?></select></label><label>Mediador<select required name="mediador_id"><option value="">Selecione</option><?php foreach($meds as $x)echo '<option value="'.$x->id.'">'.esc_html($x->nome).'</option>';?></select></label><label>Início<input type="date" name="data_inicio" value="<?php echo esc_attr(current_time('Y-m-d'));?>"></label><label>Fim<input type="date" name="data_fim"></label><button class="button button-primary">Vincular</button></form><table class="widefat striped"><thead><tr><th>Escola</th><th>Mediador</th><th>Desde</th><th>Até</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo esc_html($r->escola);?></td><td><?php echo esc_html($r->mediador);?></td><td><?php echo $r->data_inicio?esc_html(date_i18n('d/m/Y',strtotime($r->data_inicio))):'—';?></td><td><?php echo $r->data_fim?esc_html(date_i18n('d/m/Y',strtotime($r->data_fim))):'—';?></td></tr><?php endforeach;?></tbody></table></div>
